package org.jsoup.safety;

import org.jsoup.internal.StringUtil;
import org.jsoup.nodes.Attribute;
import org.jsoup.nodes.Element;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;

/**
 Validates and rewrites {@code srcset} attributes, one image candidate at a time.
 <p>
 The attribute value is split into candidates following the HTML {@code srcset} parsing rules: a candidate consists of a
 URL followed by an optional width ({@code w}) or pixel density ({@code x}) descriptor. Commas only separate
 candidates at a candidate boundary, so commas nested inside a {@code data:} URL, or inside quotes, are preserved.
 Each surviving URL is checked against the safelist with the same protocol and encoding rules used for ordinary URI
 attributes such as {@code src}; invalid descriptors cause their single candidate to be dropped, without affecting
 the other candidates.
 </p>
 */
final class SrcsetCleaner {
    private SrcsetCleaner() {}

    /**
     Determine whether the supplied attribute is a {@code srcset} attribute that should be handled candidate by
     candidate, rather than treated as an ordinary opaque attribute.
     @param attr the attribute to test
     @return true if it is a {@code srcset} attribute
     */
    static boolean isSrcset(Attribute attr) {
        return "srcset".equalsIgnoreCase(attr.getKey());
    }

    /**
     Clean a {@code srcset} attribute value into a value containing only the acceptable candidates, in their original
     order. The input element is not modified; callers must apply the returned value themselves.
     @param el the element carrying the attribute (used for URL resolution against its base URI)
     @param rawValue the original attribute value
     @param safelist the safelist to validate each candidate URL against
     @return the cleaned value, or {@code null} if no candidate survived (in which case the attribute must be removed)
     */
    static String clean(Element el, String rawValue, Safelist safelist) {
        if (rawValue == null || rawValue.isEmpty()) return null;

        List<Candidate> accepted = new ArrayList<>();
        int pos = 0;
        int len = rawValue.length();

        while (pos < len) {
            // 1. Skip a run of ASCII whitespace and candidate-separating commas.
            while (pos < len && isWsOrComma(rawValue.charAt(pos))) pos++;
            if (pos >= len) break;

            // 2. Collect the URL: a run of non-whitespace characters. A trailing comma marks the candidate boundary
            //    when there is no whitespace before it, so commas within (e.g. a data: URL) stay part of the URL.
            int urlStart = pos;
            while (pos < len && !StringUtil.isWhitespace(rawValue.charAt(pos))) pos++;
            int urlEnd = pos;
            while (urlEnd > urlStart && rawValue.charAt(urlEnd - 1) == ',') urlEnd--;

            String url = rawValue.substring(urlStart, urlEnd);

            // 3. Skip whitespace between the URL and any descriptor.
            while (pos < len && StringUtil.isWhitespace(rawValue.charAt(pos))) pos++;

            // 4. Collect a single descriptor token up to the next candidate boundary. Descriptor contents are taken
            //    verbatim so whitespace and commas inside (e.g. quoted or parenthesized values) cannot be split.
            int descStart = pos;
            while (pos < len && rawValue.charAt(pos) != ',') pos++;
            String descriptor = rawValue.substring(descStart, pos).trim();
            if (pos < len && rawValue.charAt(pos) == ',') pos++; // consume the candidate separator

            if (url.isEmpty()) continue; // empty item / consecutive separator; never fatal

            Candidate candidate = parseCandidate(url, descriptor);
            if (candidate == null) continue; // malformed descriptor: drop just this item
            if (!isSafeUrl(el, url, safelist)) continue; // fails the ordinary URI protocol/encoding checks

            accepted.add(candidate);
        }

        if (accepted.isEmpty()) return null;
        return serialize(accepted);
    }

    private static boolean isWsOrComma(char c) {
        return c == ',' || StringUtil.isWhitespace(c);
    }

    /**
     Parse a candidate URL and its optional descriptor into its normalized output form. The descriptor must be
     absent, a single valid non-negative width ({@code <integer>w}), or a single valid non-negative pixel density
     ({@code <number>x}); anything else (duplicated, unknown, or syntactically invalid) invalidates this candidate.
     @return the parsed candidate, or {@code null} if the descriptor is invalid
     */
    private static Candidate parseCandidate(String url, String descriptor) {
        if (descriptor.isEmpty()) return new Candidate(url, "");

        // Only one descriptor is permitted; whitespace implies a second token.
        for (int i = 0; i < descriptor.length(); i++) {
            if (StringUtil.isWhitespace(descriptor.charAt(i))) return null;
        }

        char suffix = descriptor.charAt(descriptor.length() - 1);
        if (suffix != 'w' && suffix != 'x') return null;
        String number = descriptor.substring(0, descriptor.length() - 1);
        if (number.isEmpty()) return null;

        if (suffix == 'w') {
            Long width = parseNonNegativeInt(number);
            if (width == null || width == 0L) return null;
        } else {
            Double density = parseNonNegativeDouble(number);
            if (density == null || density == 0d || density.isInfinite()) return null;
        }
        return new Candidate(url, " " + descriptor);
    }

    /** Parse a non-negative integer (digits only, no sign, exponent, or decimal point). */
    private static Long parseNonNegativeInt(String s) {
        long value = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') return null;
            value = value * 10 + (c - '0');
            if (value > Integer.MAX_VALUE) return null; // wider than any meaningful resource descriptor
        }
        return value;
    }

    /** Parse a finite non-negative floating point number matching the HTML valid floating-point number grammar. */
    private static Double parseNonNegativeDouble(String s) {
        int i = 0;
        int digitsBefore = 0;
        while (i < s.length() && isAsciiDigit(s.charAt(i))) { digitsBefore++; i++; }
        if (i < s.length() && s.charAt(i) == '.') {
            i++;
