     @param rawValue the original attribute value
     @param safelist the safelist to validate each candidate URL against
     @return the cleaning result; its value is {@code null} when no candidate survived, in which case the attribute
     must be removed rather than left empty
     */
    static Result clean(Element el, String rawValue, Safelist safelist) {
        List<Candidate> accepted = new ArrayList<>();
        int dropped = 0;
        if (rawValue != null && !rawValue.isEmpty()) {
            int pos = 0;
            int len = rawValue.length();

            while (pos < len) {
                // 1. Splitting loop: skip a run of ASCII whitespace and candidate-separating commas (empty items and
                //    consecutive commas are simply ignored, never an error).
                while (pos < len && isWsOrComma(rawValue.charAt(pos))) pos++;
                if (pos >= len) break;

                // 2. Collect the URL: a run of non-whitespace characters.
                int urlStart = pos;
                while (pos < len && !StringUtil.isWhitespace(rawValue.charAt(pos))) pos++;
                int urlRunEnd = pos;
                int urlEnd = urlRunEnd;
                while (urlEnd > urlStart && rawValue.charAt(urlEnd - 1) == ',') urlEnd--;
                String url = rawValue.substring(urlStart, urlEnd);

                if (urlEnd < urlRunEnd) {
                    // The URL run ended in comma(s): the boundary has no descriptor, and parsing restarts at the top
                    // of the splitting loop. This keeps commas inside a data: URL (e.g. "data:,Hello") intact.
                    if (!url.isEmpty() && isSafeUrl(el, url, safelist) != null)
                        accepted.add(new Candidate(isSafeUrl(el, url, safelist), ""));
                    else if (!url.isEmpty())
                        dropped++;
                    pos = urlRunEnd; // whitespace and commas are consumed by the next splitting step
                    continue;
                }

                // 3. Skip the whitespace between the URL and any descriptor.
                while (pos < len && StringUtil.isWhitespace(rawValue.charAt(pos))) pos++;

                // 4. Collect the descriptor run up to the next candidate boundary. A syntactically valid width or
                //    density descriptor never contains whitespace or a comma, so taking the run verbatim and then
