/** Parse a finite non-negative floating-point number matching the HTML valid floating-point number grammar. */
private static Double parseDensity(String s) {
    int i = 0;
    if (i < s.length() && (s.charAt(i) == '+' || s.charAt(i) == '-')) {
        if (s.charAt(i) == '-') return null;
        i++;
    }
    int intDigits = 0;
    while (i < s.length() && isAsciiDigit(s.charAt(i))) { intDigits++; i++; }
    int fracDigits = 0;
    if (i < s.length() && s.charAt(i) == '.') {
        i++;
        while (i < s.length() && isAsciiDigit(s.charAt(i))) { fracDigits++; i++; }
        if (fracDigits == 0) return null; // a decimal point must be followed by digits
    }
    if (intDigits + fracDigits == 0) return null;
    if (i < s.length() && (s.charAt(i) == 'e' || s.charAt(i) == 'E')) {
        i++;
        if (i < s.length() && (s.charAt(i) == '+' || s.charAt(i) == '-')) i++;
        int exponentDigits = 0;
        while (i < s.length() && isAsciiDigit(s.charAt(i))) { exponentDigits++; i++; }
        if (exponentDigits == 0) return null;
    }
    if (i != s.length()) return null; // trailing junk
    try {
        double value = Double.parseDouble(s);
        // the HTML spec only rejects negative densities here; zero is a grammatical, if odd, density
        if (value < 0d || Double.isNaN(value) || Double.isInfinite(value)) return null;
        return value;
    } catch (NumberFormatException e) {
        return null;
    }
}

